func numTrees(n int) int {
	if n<1{
		return 0
	}
	dp:=make([]int,n+1)
	dp[0] = 1;dp[1] = 1;
	for i:=2;i<=n;i++{
		for j:=1;j<=i;j++{
			dp[i]+=dp[j-1]*dp[i-j]
		}
	}
	return dp[n]

}
